CREATE TABLE eta_model_version ("prediction_version" VARCHAR NOT NULL,"training_cutoff_at" TIMESTAMPTZ NOT NULL,"feature_definition_version" VARCHAR NOT NULL,"nominal_interval_coverage" DECIMAL(7,6) NOT NULL,"split_version" VARCHAR NOT NULL,"interval_calibration_version" VARCHAR NOT NULL,"probability_calibration_version" VARCHAR NOT NULL,"calibration_cutoff_at" TIMESTAMPTZ NOT NULL,"baseline_definition" VARCHAR NOT NULL,PRIMARY KEY (prediction_version),CHECK (nominal_interval_coverage>0 AND nominal_interval_coverage<1));

CREATE TABLE p08_model_binding ("tenant_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"source_bindings" JSON NOT NULL,PRIMARY KEY (tenant_id,prediction_version),UNIQUE (prediction_version),FOREIGN KEY (prediction_version) REFERENCES eta_model_version (prediction_version));

CREATE TABLE p08_source_trip ("tenant_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"vehicle_id" VARCHAR NOT NULL,"route_id" VARCHAR NOT NULL,"departure_time" TIMESTAMPTZ NOT NULL,"unseen_vehicle" BOOLEAN NOT NULL,"unseen_route" BOOLEAN NOT NULL,PRIMARY KEY (tenant_id,trip_id));

CREATE TABLE p08_provenance_reference ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"reference_kind" VARCHAR NOT NULL,"source_reference" VARCHAR NOT NULL,"source_sha256" VARCHAR NOT NULL,"record_key" JSON NOT NULL,"parent_provenance_ids" JSON NOT NULL,"recorded_at" TIMESTAMPTZ NOT NULL,PRIMARY KEY (tenant_id,provenance_id));

CREATE TABLE p08_source_snapshot ("tenant_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_time" TIMESTAMPTZ NOT NULL,"promise_version_id" VARCHAR NOT NULL,"deadline_at" TIMESTAMPTZ NOT NULL,"promise_known_at" TIMESTAMPTZ NOT NULL,"snapshot_provenance_id" VARCHAR NOT NULL,"promise_provenance_id" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p08_source_trip (tenant_id,trip_id),FOREIGN KEY (tenant_id,snapshot_provenance_id) REFERENCES p08_provenance_reference (tenant_id,provenance_id),FOREIGN KEY (tenant_id,promise_provenance_id) REFERENCES p08_provenance_reference (tenant_id,provenance_id));

CREATE TABLE eta_evaluation_membership ("tenant_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"split_version" VARCHAR NOT NULL,"lead_time_slice" VARCHAR NOT NULL,"unseen_route" BOOLEAN NOT NULL,"trip_evaluation_weight" DECIMAL(12,9) NOT NULL,"evaluation_slice" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,split_version),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p08_source_snapshot (tenant_id,snapshot_id));

CREATE TABLE eta_prediction ("tenant_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"eta_median" TIMESTAMPTZ NOT NULL,"eta_lower" TIMESTAMPTZ NOT NULL,"eta_upper" TIMESTAMPTZ NOT NULL,"delay_probability" DECIMAL(7,6),"fallback_reason" VARCHAR NOT NULL,"remaining_eta_seconds" BIGINT NOT NULL,"generated_at" TIMESTAMPTZ NOT NULL,"value_states" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,prediction_version),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p08_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p08_model_binding (tenant_id,prediction_version),CHECK (delay_probability IS NULL OR delay_probability BETWEEN 0 AND 1),CHECK (remaining_eta_seconds>=0 AND eta_lower<=eta_median AND eta_median<=eta_upper));

CREATE TABLE p08_rule_audit ("policy_version" VARCHAR NOT NULL,"enabled" BOOLEAN NOT NULL,"threshold" DECIMAL(7,6),"selection_status" VARCHAR NOT NULL,"experimental" BOOLEAN NOT NULL,"quality_limits" JSON NOT NULL,"rule" JSON NOT NULL,"selection_manifest" JSON NOT NULL,PRIMARY KEY (policy_version));

CREATE TABLE eta_alert_rule_version ("decision_threshold_version" VARCHAR NOT NULL,"delay_alert_threshold" DECIMAL(7,6) NOT NULL,"minimum_action_lead_seconds" INTEGER NOT NULL,"repeat_suppression_seconds" INTEGER NOT NULL,"threshold_selection_ref" VARCHAR NOT NULL,PRIMARY KEY (decision_threshold_version),FOREIGN KEY (decision_threshold_version) REFERENCES p08_rule_audit (policy_version));

CREATE TABLE p08_opportunity_audit ("tenant_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"snapshot_time" TIMESTAMPTZ NOT NULL,"prediction_version" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"eta_status" VARCHAR NOT NULL,"probability_status" VARCHAR NOT NULL,"probability" DECIMAL(7,6),"lower_seconds" DOUBLE,"median_seconds" DOUBLE,"upper_seconds" DOUBLE,"lower_seconds_int" BIGINT,"median_seconds_int" BIGINT,"upper_seconds_int" BIGINT,"canonical_prediction_written" BOOLEAN NOT NULL,"generated_at" TIMESTAMPTZ NOT NULL,"opportunity" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,prediction_version),UNIQUE (tenant_id,output_id),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p08_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p08_model_binding (tenant_id,prediction_version));

CREATE TABLE eta_output_release ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"released_at" TIMESTAMPTZ NOT NULL,"release_mode" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,output_id),FOREIGN KEY (tenant_id,output_id) REFERENCES p08_opportunity_audit (tenant_id,output_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p08_model_binding (tenant_id,prediction_version),FOREIGN KEY (tenant_id,provenance_id) REFERENCES p08_provenance_reference (tenant_id,provenance_id));

CREATE TABLE p08_episode_audit ("tenant_id" VARCHAR NOT NULL,"episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"policy_version" VARCHAR NOT NULL,"research_episode" JSON NOT NULL,PRIMARY KEY (tenant_id,episode_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p08_source_trip (tenant_id,trip_id),FOREIGN KEY (policy_version) REFERENCES p08_rule_audit (policy_version));

CREATE TABLE p08_candidate_audit ("tenant_id" VARCHAR NOT NULL,"candidate_id" VARCHAR NOT NULL,"episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"policy_version" VARCHAR NOT NULL,"simulated_issue_at" TIMESTAMPTZ NOT NULL,"probability" DECIMAL(7,6) NOT NULL,"created_at" TIMESTAMPTZ NOT NULL,"research_candidate" JSON NOT NULL,PRIMARY KEY (tenant_id,candidate_id),FOREIGN KEY (tenant_id,episode_id) REFERENCES p08_episode_audit (tenant_id,episode_id),FOREIGN KEY (tenant_id,output_id) REFERENCES eta_output_release (tenant_id,output_id),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p08_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p08_model_binding (tenant_id,prediction_version),FOREIGN KEY (policy_version) REFERENCES p08_rule_audit (policy_version));

CREATE TABLE p08_decision_audit ("tenant_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"snapshot_time" TIMESTAMPTZ NOT NULL,"prediction_version" VARCHAR NOT NULL,"policy_version" VARCHAR NOT NULL,"candidate_status" VARCHAR NOT NULL,"candidate_id" VARCHAR,"episode_id" VARCHAR,"lead_seconds" DOUBLE NOT NULL,"probability" DECIMAL(7,6),"reason" VARCHAR NOT NULL,"decision" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,prediction_version,policy_version),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p08_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p08_model_binding (tenant_id,prediction_version),FOREIGN KEY (policy_version) REFERENCES p08_rule_audit (policy_version),FOREIGN KEY (tenant_id,candidate_id) REFERENCES p08_candidate_audit (tenant_id,candidate_id),FOREIGN KEY (tenant_id,episode_id) REFERENCES p08_episode_audit (tenant_id,episode_id));

CREATE TABLE p08_run_audit ("scenario_id" VARCHAR NOT NULL,"store_version" VARCHAR NOT NULL,"protocol_version" VARCHAR NOT NULL,"settings_sha256" VARCHAR NOT NULL,"metadata_sha256" VARCHAR NOT NULL,"registry" JSON NOT NULL,"bundle_sha256" VARCHAR NOT NULL,"bundle_header" JSON NOT NULL,"policy_summary" JSON NOT NULL,"delivery_summary" JSON NOT NULL,"selection_manifest" JSON NOT NULL,"counts_as_of" TIMESTAMPTZ NOT NULL,"materialized_at" TIMESTAMPTZ NOT NULL,"population_role" VARCHAR NOT NULL,"quality_accepted" BOOLEAN NOT NULL,"operational_approval" BOOLEAN NOT NULL,"target_rows_read" BOOLEAN NOT NULL,PRIMARY KEY (scenario_id),CHECK (population_role='final_test'),CHECK (NOT quality_accepted AND NOT operational_approval AND NOT target_rows_read));

CREATE TABLE p08_metadata_audit ("tenant_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"scenario_id" VARCHAR NOT NULL,"opportunity" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p08_source_snapshot (tenant_id,snapshot_id));

CREATE TABLE p08_delivery_provenance_reference ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"reference_kind" VARCHAR NOT NULL,"source_reference" VARCHAR NOT NULL,"source_sha256" VARCHAR NOT NULL,"record_key" JSON NOT NULL,"parent_provenance_ids" JSON NOT NULL,"recorded_at" TIMESTAMPTZ NOT NULL,"result_origin" VARCHAR NOT NULL,"clock_domain" VARCHAR NOT NULL,"materialized_at" TIMESTAMPTZ NOT NULL,PRIMARY KEY (tenant_id,provenance_id),CHECK (result_origin='synthetic_scenario'),CHECK (clock_domain='synthetic_scenario_time'));

CREATE TABLE eta_alert_episode ("tenant_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"episode_started_at" TIMESTAMPTZ NOT NULL,"episode_closed_at" TIMESTAMPTZ,"delivered_alert_count" INTEGER NOT NULL,"duplicate_alert_count" INTEGER NOT NULL,"counts_as_of" TIMESTAMPTZ NOT NULL,"value_states" JSON NOT NULL,PRIMARY KEY (tenant_id,alert_episode_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p08_source_trip (tenant_id,trip_id),FOREIGN KEY (tenant_id,alert_episode_id) REFERENCES p08_episode_audit (tenant_id,episode_id),CHECK (delivered_alert_count>=0 AND duplicate_alert_count=greatest(delivered_alert_count-1,0)));

CREATE TABLE eta_alert ("tenant_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"decision_threshold_version" VARCHAR NOT NULL,"created_at" TIMESTAMPTZ NOT NULL,"alert_status" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,alert_id),FOREIGN KEY (tenant_id,alert_episode_id) REFERENCES eta_alert_episode (tenant_id,alert_episode_id),FOREIGN KEY (tenant_id,output_id) REFERENCES eta_output_release (tenant_id,output_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p08_source_trip (tenant_id,trip_id),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p08_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p08_model_binding (tenant_id,prediction_version),FOREIGN KEY (decision_threshold_version) REFERENCES eta_alert_rule_version (decision_threshold_version),CHECK (alert_status IN ('queued','suppressed','no_action_lead','delivered','failed')));

CREATE TABLE eta_notification_delivery ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"delivery_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"recipient_role" VARCHAR NOT NULL,"delivered_at" TIMESTAMPTZ,"received_or_opened_at" TIMESTAMPTZ,"receipt_type" VARCHAR NOT NULL,"delivery_status" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,delivery_id),FOREIGN KEY (tenant_id,alert_id) REFERENCES eta_alert (tenant_id,alert_id),FOREIGN KEY (tenant_id,provenance_id) REFERENCES p08_delivery_provenance_reference (tenant_id,provenance_id),CHECK (delivery_status IN ('queued','delivered','failed','unknown')),CHECK (recipient_role IN ('dispatcher','demo_reviewer')),CHECK (received_or_opened_at IS NULL),CHECK ((delivery_status='delivered' AND delivered_at IS NOT NULL AND receipt_type='service_delivered') OR (delivery_status<>'delivered' AND delivered_at IS NULL AND receipt_type='none')));

CREATE TABLE p08_delivery_episode_audit ("tenant_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"episode_started_at" TIMESTAMPTZ NOT NULL,"episode_closed_at" TIMESTAMPTZ,"delivered_alert_count" INTEGER NOT NULL,"duplicate_alert_count" INTEGER NOT NULL,"counts_as_of" TIMESTAMPTZ NOT NULL,"value_states" JSON NOT NULL,"policy_version" VARCHAR NOT NULL,"source_episode_status" VARCHAR NOT NULL,"source_closure_reason" VARCHAR,"censored_at" TIMESTAMPTZ,"original_candidate_count" INTEGER NOT NULL,"alert_count" INTEGER NOT NULL,"result_origin" VARCHAR NOT NULL,"clock_domain" VARCHAR NOT NULL,"materialized_at" TIMESTAMPTZ NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,alert_episode_id),FOREIGN KEY (tenant_id,alert_episode_id) REFERENCES eta_alert_episode (tenant_id,alert_episode_id),CHECK (result_origin='synthetic_scenario'),CHECK (clock_domain='synthetic_scenario_time'));

CREATE TABLE p08_delivery_alert_audit ("tenant_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"candidate_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"decision_threshold_version" VARCHAR NOT NULL,"created_at" TIMESTAMPTZ NOT NULL,"promise_version_id" VARCHAR NOT NULL,"deadline_at" TIMESTAMPTZ NOT NULL,"probability" DECIMAL(7,6) NOT NULL,"alert_status" VARCHAR NOT NULL,"status_reason" VARCHAR NOT NULL,"first_delivery_id" VARCHAR,"first_delivered_at" TIMESTAMPTZ,"attempt_count" INTEGER NOT NULL,"result_origin" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"clock_domain" VARCHAR NOT NULL,"materialized_at" TIMESTAMPTZ NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,alert_id),UNIQUE (tenant_id,candidate_id),FOREIGN KEY (tenant_id,alert_id) REFERENCES eta_alert (tenant_id,alert_id),FOREIGN KEY (tenant_id,candidate_id) REFERENCES p08_candidate_audit (tenant_id,candidate_id),CHECK (result_origin='synthetic_scenario'),CHECK (clock_domain='synthetic_scenario_time'));

CREATE TABLE p08_delivery_attempt_audit ("tenant_id" VARCHAR NOT NULL,"delivery_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"candidate_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"decision_threshold_version" VARCHAR NOT NULL,"promise_version_id" VARCHAR NOT NULL,"deadline_at" TIMESTAMPTZ NOT NULL,"attempt_index" INTEGER NOT NULL,"sent_at" TIMESTAMPTZ NOT NULL,"scheduled_service_at" TIMESTAMPTZ,"service_at" TIMESTAMPTZ,"service_outcome" VARCHAR,"scheduled_receipt_at" TIMESTAMPTZ,"receipt_known_at" TIMESTAMPTZ,"delivered_at" TIMESTAMPTZ,"delivery_status" VARCHAR NOT NULL,"attempt_status" VARCHAR NOT NULL,"error_reason" VARCHAR,"retryable" BOOLEAN NOT NULL,"retry_scheduled_at" TIMESTAMPTZ,"receipt_observed" BOOLEAN NOT NULL,"receipt_type" VARCHAR NOT NULL,"recipient_role" VARCHAR NOT NULL,"received_or_opened_at" TIMESTAMPTZ,"result_origin" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"clock_domain" VARCHAR NOT NULL,"materialized_at" TIMESTAMPTZ NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,delivery_id),UNIQUE (tenant_id,alert_id,attempt_index),FOREIGN KEY (tenant_id,delivery_id) REFERENCES eta_notification_delivery (tenant_id,delivery_id),FOREIGN KEY (tenant_id,alert_id) REFERENCES eta_alert (tenant_id,alert_id),FOREIGN KEY (tenant_id,candidate_id) REFERENCES p08_candidate_audit (tenant_id,candidate_id),CHECK (result_origin='synthetic_scenario'),CHECK (clock_domain='synthetic_scenario_time'));

CREATE TABLE p08_delivery_event_audit ("event_id" VARCHAR NOT NULL,"event_type" VARCHAR NOT NULL,"event_at" TIMESTAMPTZ NOT NULL,"tenant_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR,"alert_id" VARCHAR,"delivery_id" VARCHAR,"candidate_id" VARCHAR,"attempt_index" INTEGER,"event_status" VARCHAR NOT NULL,"event_reason" VARCHAR,"result_origin" VARCHAR NOT NULL,"clock_domain" VARCHAR NOT NULL,"materialized_at" TIMESTAMPTZ NOT NULL,"record" JSON NOT NULL,"event_order" INTEGER NOT NULL,PRIMARY KEY (tenant_id,event_id),UNIQUE (event_order),FOREIGN KEY (tenant_id,trip_id) REFERENCES p08_source_trip (tenant_id,trip_id),FOREIGN KEY (tenant_id,alert_episode_id) REFERENCES eta_alert_episode (tenant_id,alert_episode_id),FOREIGN KEY (tenant_id,alert_id) REFERENCES eta_alert (tenant_id,alert_id),FOREIGN KEY (tenant_id,delivery_id) REFERENCES eta_notification_delivery (tenant_id,delivery_id),FOREIGN KEY (tenant_id,candidate_id) REFERENCES p08_candidate_audit (tenant_id,candidate_id),CHECK (result_origin='synthetic_scenario'),CHECK (clock_domain='synthetic_scenario_time'));

CREATE TABLE p09_run_audit ("store_version" VARCHAR NOT NULL,"parent_commit" VARCHAR NOT NULL,"scenario_id" VARCHAR NOT NULL,"materialized_at" TIMESTAMPTZ NOT NULL,"settings_sha256" VARCHAR NOT NULL,"workflow_settings" JSON NOT NULL,"simulation_sha256" VARCHAR NOT NULL,"simulation_summary" JSON NOT NULL,"parent_table_sha256" JSON NOT NULL,"quality_accepted" BOOLEAN NOT NULL,"operational_approval" BOOLEAN NOT NULL,PRIMARY KEY (store_version),CHECK (NOT quality_accepted AND NOT operational_approval),CHECK (scenario_id='S00_unmodified'));

CREATE TABLE p09_promise_reference ("tenant_id" VARCHAR NOT NULL,"promise_version_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"known_at" TIMESTAMPTZ NOT NULL,"window_start_at" TIMESTAMPTZ NOT NULL,"window_end_at" TIMESTAMPTZ NOT NULL,"reference_origin" VARCHAR NOT NULL,"record_sha256" VARCHAR NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,promise_version_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p08_source_trip (tenant_id,trip_id),CHECK (window_start_at<=window_end_at),CHECK (reference_origin IN ('retained_p08_promise','synthetic_p09_revision')));

CREATE TABLE p09_outcome_reference ("tenant_id" VARCHAR NOT NULL,"outcome_version_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"label_available_time" TIMESTAMPTZ NOT NULL,"actual_arrival_time" TIMESTAMPTZ,"followup_through" TIMESTAMPTZ NOT NULL,"label_status" VARCHAR NOT NULL,"record_sha256" VARCHAR NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,outcome_version_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p08_source_trip (tenant_id,trip_id));

CREATE TABLE p09_provenance_reference ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"entity_table" VARCHAR NOT NULL,"entity_key" JSON NOT NULL,"record_sha256" VARCHAR NOT NULL,"result_origin" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,provenance_id),CHECK (result_origin='synthetic_scenario'));

CREATE TABLE eta_adoption ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"adoption_id" VARCHAR NOT NULL,"delivery_id" VARCHAR NOT NULL,"adoption_status" VARCHAR NOT NULL,"adoption_reason" VARCHAR,"decided_at" TIMESTAMPTZ,PRIMARY KEY (tenant_id,adoption_id),FOREIGN KEY (tenant_id,delivery_id) REFERENCES eta_notification_delivery (tenant_id,delivery_id),FOREIGN KEY (tenant_id,provenance_id) REFERENCES p09_provenance_reference (tenant_id,provenance_id),UNIQUE (tenant_id,delivery_id),CHECK (adoption_status IN ('accepted','partially_accepted','rejected','not_reviewed','overridden')),CHECK ((adoption_status='not_reviewed' AND decided_at IS NULL) OR (adoption_status<>'not_reviewed' AND decided_at IS NOT NULL)));

CREATE TABLE eta_action ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"action_id" VARCHAR NOT NULL,"adoption_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"action_type" VARCHAR NOT NULL,"action_time" TIMESTAMPTZ,"handling_seconds" INTEGER,PRIMARY KEY (tenant_id,action_id),FOREIGN KEY (tenant_id,adoption_id) REFERENCES eta_adoption (tenant_id,adoption_id),FOREIGN KEY (tenant_id,alert_id) REFERENCES eta_alert (tenant_id,alert_id),FOREIGN KEY (tenant_id,provenance_id) REFERENCES p09_provenance_reference (tenant_id,provenance_id),CHECK (action_type IN ('contact_driver','contact_customer','reschedule','reassign','no_action','other')),CHECK (handling_seconds IS NULL OR handling_seconds>=0));

CREATE TABLE eta_action_followup ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"action_id" VARCHAR NOT NULL,"outcome_version_id" VARCHAR NOT NULL,"followup_promise_version_id" VARCHAR NOT NULL,"original_promise_version_id" VARCHAR NOT NULL,"outcome_observation_end" TIMESTAMPTZ NOT NULL,"observed_delay_seconds" BIGINT,"original_promise_delay_seconds" BIGINT,"review_outcome" VARCHAR NOT NULL,"result_origin" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,action_id,outcome_version_id),FOREIGN KEY (tenant_id,action_id) REFERENCES eta_action (tenant_id,action_id),FOREIGN KEY (tenant_id,outcome_version_id) REFERENCES p09_outcome_reference (tenant_id,outcome_version_id),FOREIGN KEY (tenant_id,original_promise_version_id) REFERENCES p09_promise_reference (tenant_id,promise_version_id),FOREIGN KEY (tenant_id,followup_promise_version_id) REFERENCES p09_promise_reference (tenant_id,promise_version_id),FOREIGN KEY (tenant_id,provenance_id) REFERENCES p09_provenance_reference (tenant_id,provenance_id),CHECK (review_outcome IN ('confirmed','rejected','disputed','not_reported','open','lost')),CHECK (result_origin='synthetic_scenario'),CHECK (observed_delay_seconds IS NULL OR observed_delay_seconds>=0),CHECK (original_promise_delay_seconds IS NULL OR original_promise_delay_seconds>=0));

CREATE TABLE p09_opening_audit ("tenant_id" VARCHAR NOT NULL,"record_id" VARCHAR NOT NULL,"record_sha256" VARCHAR NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,record_id));

CREATE TABLE p09_decision_audit ("tenant_id" VARCHAR NOT NULL,"record_id" VARCHAR NOT NULL,"record_sha256" VARCHAR NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,record_id));

CREATE TABLE p09_followup_audit ("tenant_id" VARCHAR NOT NULL,"record_id" VARCHAR NOT NULL,"record_sha256" VARCHAR NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,record_id));

CREATE TABLE p09_event_audit ("tenant_id" VARCHAR NOT NULL,"record_id" VARCHAR NOT NULL,"record_sha256" VARCHAR NOT NULL,"record" JSON NOT NULL,PRIMARY KEY (tenant_id,record_id));
